<?phpnamespace app\api\model;use app\common\model\Goods as GoodsModel;class Goods extends GoodsModel{    /**     * 隐藏字段     */    protected $hidden = [];    	/**     * 按照分类获取上架的所有商品     */	public function getGoodsList($category,$user_id,$order_mode,$table_id=0)	{		//获取当前购物车商品		$cart = new Cart($user_id,$table_id);		$cart_data = $cart->getCart();//购物车缓存数据		$cartlist = $cart->getList($order_mode);		$goodsSetting = Setting::getItem('goods');//获取商品配置		for($i=0;$i<sizeof($category);$i++){		    // 筛选条件            $filter = [				'category_id' => $category[$i]['category_id'],				'is_delete' => 0,			];			//下架是否显示			if($goodsSetting['delisting'] == 0){			    $filter['goods_status'] = 10;			}			$goods = $this->with(['spec', 'image', 'spec_rel.spec'])						->where($filter)						->order(['goods_sort', 'goods_id' => 'desc'])						->select()->toArray();			$tempArr = [];//临时数组			//筛选是否显示售罄商品			foreach ($goods as $item){			    //判断是否开启库存			    if($goodsSetting['is_stock'] == 1 and $item['stock'] < 1 and $goodsSetting['sell_out'] == 0){			        continue;    			}    			$tempArr[] = $item;			}			$goods = $tempArr;			for($n=0;$n<sizeof($goods);$n++){				$goods[$n]['total_num'] = 0;//购物车数量				if($goods[$n]['spec_type'] == 20){					$goods[$n]['specData'] = $this->getManySpecData($goods[$n]['spec_rel'], $goods[$n]['spec']);					for($s=0;$s<sizeof($goods[$n]['spec']);$s++){						$goods[$n]['spec'][$s]['sell_num'] = 0;						if(isset($cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']])){							$goods[$n]['total_num'] = $goods[$n]['total_num'] + $cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']]['goods_num'];								$goods[$n]['spec'][$s]['sell_num'] = $cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']]['goods_num'];						}					}				}else{					if(isset($cart_data[$goods[$n]['goods_id'].'_'])){						$goods[$n]['total_num'] = $cart_data[$goods[$n]['goods_id'].'_']['goods_num'];						}					$goods[$n]['specData'] = null;				}			}			$category[$i]['goods'] = $goods;		}				//获取推荐商品		// 筛选条件        $filter = [			'is_recommend' => 1,			'is_delete' => 0,		];		//下架是否显示		if($goodsSetting['delisting'] == 0){		    $filter['goods_status'] = 10;		}		$goods = $this->with(['image', 'spec', 'spec.image', 'spec_rel.spec'])->where($filter)->select()->toArray();		$tempArr = [];//临时数组		//筛选是否显示售罄商品		foreach ($goods as $item){		    //判断是否开启库存		    if($goodsSetting['is_stock'] == 1 and $item['stock'] < 1 and $goodsSetting['sell_out'] == 0){		        continue;			}			$tempArr[] = $item;		}		$goods = $tempArr;		if(sizeof($goods)){		    for($n=0;$n<sizeof($goods);$n++){				$goods[$n]['total_num'] = 0;//购物车数量				if($goods[$n]['spec_type'] == 20){					$goods[$n]['specData'] = $this->getManySpecData($goods[$n]['spec_rel'], $goods[$n]['spec']);					for($s=0;$s<sizeof($goods[$n]['spec']);$s++){						$goods[$n]['spec'][$s]['sell_num'] = 0;						if(isset($cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']])){							$goods[$n]['total_num'] = $goods[$n]['total_num'] + $cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']]['goods_num'];								$goods[$n]['spec'][$s]['sell_num'] = $cart_data[$goods[$n]['goods_id'].'_'.$goods[$n]['spec'][$s]['spec_sku_id']]['goods_num'];						}					}				}else{					if(isset($cart_data[$goods[$n]['goods_id'].'_'])){						$goods[$n]['total_num'] = $cart_data[$goods[$n]['goods_id'].'_']['goods_num'];						}					$goods[$n]['specData'] = null;				}			}		    array_unshift($category,[		        'category_id' => 10000,		        'name' => '商家推荐',		        'goods' => $goods		    ]);		}		return compact('category','cartlist');	}		/**     * 获取商品列表 - DIY组件     */    public static function getAll($sortType = 'all',$limit=null)    {        $goodsSetting = Setting::getItem('goods');//获取商品配置        // 筛选条件        $filter = [];        //下架是否显示		if($goodsSetting['delisting'] == 0){		    $filter['goods_status'] = 10;		}        if($sortType == 'recommend'){            $filter['is_recommend'] = 1;//推荐商品        }        // 排序规则        $sort = [];        if ($sortType === 'all') {            $sort = ['goods_sales' => 'desc','goods_id' => 'desc'];        } elseif ($sortType === 'sales') {            $sort = ['goods_sales' => 'desc'];        } elseif ($sortType === 'new') {            $sort = ['goods_id' => 'desc'];        }        // 执行查询        $goods = self::with(['image', 'spec'])            ->where('is_delete', '=', 0)            ->where($filter)            ->order($sort)            ->limit($limit)            ->select()            ->toArray();        $list = [];//临时数组		//筛选是否显示售罄商品		foreach ($goods as $item){		    //判断是否开启库存		    if($goodsSetting['is_stock'] == 1 and $item['stock'] < 1 and $goodsSetting['sell_out'] == 0){		        continue;			}			$list[] = $item;		}		return $list;    }}